                theMap.mapboxMap.removeSource(id);
                let offset = this.lines.findIndex((entry) => { return entry.id == id; });
                if (offset != -1) {
                    this.lines.splice(offset, 1);
                }
                offset = this.circles.findIndex((entry) => { return entry.id == id; });
